INSERT OR REPLACE INTO "meta" VALUES('built_at','1795007045');
INSERT OR REPLACE INTO "units" VALUES(1217000100,'高达杰姆纳斯01','高达杰姆纳斯01',2,2,0,0,'10000000021702100','2170','g2170u00100','OZX-GU01A',1,1,1,1,6847,52,716,743,582,4,36559,138,3822,3965,2777,4,67493,241,7057,7320,5093,4,3,1,3,1,2,'于资源卫星殖民地“MO-V”秘密研发的试作型MS一号机。
以设有驾驶舱的本体作为核心组件，该机体通过在各部位搭配适用于不同用途的“G-UNIT”零件，力求在各种环境下都能发挥优异性能。
该机体的基础性能远超量产型MS，同时还配备了加速步枪、光束剑等多种武装。
此外，还搭载了可根据驾驶员的精神状态，在一定时间内提升机体性能的“PX系统”，但发动此系统需要一定的天赋及训练，并且必须依照各个驾驶员调校系统。',NULL,'{"unit_id": 1217000100, "unit_ssp_initial_release_set_id": 1217000100, "unit_ssp_custom_core_group_id": 1217000100, "unit_ssp_add_status_id": 100016, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100016, "ssp_hp": 240, "ssp_en": 1, "ssp_attack": 25, "ssp_defense": 26, "ssp_mobility": 21, "ssp_max_hp": 4806, "ssp_max_en": 15, "ssp_max_attack": 503, "ssp_max_defense": 526, "ssp_max_mobility": 412}}','高达杰姆纳斯01','master',1794971433,'v2026.11.18',NULL,'["2170", "2100"]');
INSERT OR REPLACE INTO "units" VALUES(1217000200,'高达杰姆纳斯01(突击推进器装备)','高达杰姆纳斯01(突击推进器装备)',3,3,0,0,'10000000021702100','2170','g2170u00200','OZX-GU01A',1,1,1,1,6670,70,738,662,739,5,39753,189,4394,3945,4196,5,61059,279,6749,6060,6435,5,3,1,3,1,2,'杰姆纳斯01装备宇宙用推进器组件的型态。
于肩部、脚部及背部加装推进器，大幅提升在宇宙中的机动性。
开发初期以杰姆纳斯称呼此机体，但是测试驾驶员安迪·班奈特赋予其“为了自由及殖民地而战的高达”的含意，而被命名为“高达杰姆纳斯”。',NULL,'{"unit_id": 1217000200, "unit_ssp_initial_release_set_id": 1217000200, "unit_ssp_custom_core_group_id": 1217000200, "unit_ssp_add_status_id": 100012, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100012, "ssp_hp": 217, "ssp_en": 1, "ssp_attack": 24, "ssp_defense": 22, "ssp_mobility": 24, "ssp_max_hp": 4348, "ssp_max_en": 19, "ssp_max_attack": 481, "ssp_max_defense": 435, "ssp_max_mobility": 481}}','高达杰姆纳斯01(突击推进器装备)','master',1794971433,'v2026.11.18',NULL,'["2170", "2100"]');
INSERT OR REPLACE INTO "units" VALUES(1217000300,'高达杰姆纳斯02','高达杰姆纳斯02',2,3,0,0,'10000000021702100','2170','g2170u00300','OZX-GU02A',1,1,1,1,6471,65,678,586,686,4,34554,163,3620,3124,3497,4,63792,281,6684,5768,6439,4,3,1,3,1,2,'资源卫星殖民地“MO-V”机密开发出的试作型MS二号机。
将本体驾驶舱作为核心组件，各部位则依据不同用途组合相对应的零件“G-UNIT”，期望在各种环境下都能发挥高性能的机体。
作为识别将涂装改成蓝色，机体性能基本上与一号机没有不同。',NULL,'{"unit_id": 1217000300, "unit_ssp_initial_release_set_id": 1217000300, "unit_ssp_custom_core_group_id": 1217000300, "unit_ssp_add_status_id": 100014, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100014, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 24, "ssp_defense": 21, "ssp_mobility": 24, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 481, "ssp_max_defense": 412, "ssp_max_mobility": 481}}','高达杰姆纳斯02','master',1794971433,'v2026.11.18',NULL,'["2170", "2100"]');
INSERT OR REPLACE INTO "units" VALUES(1217000400,'高达杰姆纳斯02(突击推进器装备)','高达杰姆纳斯02(突击推进器装备)',3,1,0,0,'10000000021702100','2170','g2170u00400','OZX-GU02A',1,1,1,1,6308,71,803,664,700,5,37593,183,4783,3955,4168,5,57742,269,7347,6075,6403,5,3,1,3,1,2,'杰姆纳斯02装备宇宙用推进组件的型态。
于肩部、脚部及背部加装推进器，大幅提升在宇宙空间中的机动性。
在与OZ普莱斯的“星屑三骑士 (Stardust Knights)”的战斗中，为了保护一号机而冲入宇宙机雷群中，机体严重受损。',NULL,'{"unit_id": 1217000400, "unit_ssp_initial_release_set_id": 1217000400, "unit_ssp_custom_core_group_id": 1217000400, "unit_ssp_add_status_id": 100002, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100002, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 23, "ssp_max_hp": 4119, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 458}}','高达杰姆纳斯02(突击推进器装备)','master',1794971433,'v2026.11.18',NULL,'["2170", "2100"]');
INSERT OR REPLACE INTO "units" VALUES(1217000500,'韦依埃度·休潘','韦依埃度·休潘',3,3,0,0,'10000000021702100','2170','g2170u00500','OZ-13MSX1B-S',1,1,1,1,6976,70,667,705,736,4,41574,189,3970,4200,4183,4,63856,278,6098,6451,6414,4,3,1,3,1,2,'隶属于OZ普莱斯的韦依埃度特装机。
将OZ开发的韦依埃度进行改装，各装备上两座光束加农及动力炉，拥有远优于原机的火力。
用于OZ普莱斯的指挥官瓦尔达·法奇尔的亲卫队机。',NULL,'{"unit_id": 1217000500, "unit_ssp_initial_release_set_id": 1217000500, "unit_ssp_custom_core_group_id": 1217000500, "unit_ssp_add_status_id": 100013, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100013, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 23, "ssp_mobility": 24, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 435, "ssp_max_defense": 458, "ssp_max_mobility": 481}}','韦依埃度·休潘','master',1794971433,'v2026.11.18',NULL,'["2170", "2100"]');
INSERT OR REPLACE INTO "units" VALUES(1217000600,'海德拉高达','海德拉高达',4,3,0,0,'10000000021702100','2170','g2170u00600','OZ-15AGX',1,1,1,1,7963,81,843,717,846,5,52393,235,5545,4713,5305,5,63779,281,6751,5738,6453,5,3,3,3,1,2,'为了对抗宇宙殖民地独立组织开发的五架高达，由OZ开发的高性能试作MS。
但是也有传言说实际上的假想敌是艾比安高达。
具备将双脚收纳后下半身整体变成推进系统的简易变形构造，在宇宙空间的机动性凌驾其他机体之上。
此外，更搭载「精神感应系统」，将驾驶员的神经与传感器群连结，进而掌握周遭空间的状况，并能仅凭意识便可朝目标攻击。
主武装为装备在肩部的强力破坏加农，格斗战时则可从背部展开肩部钩爪。
肩部钩爪还可以与本体分离，以有线操作的方式进行远距离攻击。',NULL,'{"unit_id": 1217000600, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1217000600, "unit_ssp_add_status_id": 100014, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100014, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 24, "ssp_defense": 21, "ssp_mobility": 24, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 481, "ssp_max_defense": 412, "ssp_max_mobility": 481}}','海德拉高达','master',1794971433,'v2026.11.18',1217000400,'["2170", "2100"]');
INSERT OR REPLACE INTO "units" VALUES(1217000700,'D模组','D模组',1,1,0,0,'10000000021702100','2170','g2170u00700','-',1,1,1,1,5411,61,685,571,601,4,25539,133,3233,2692,2833,4,57788,268,7316,6092,6411,4,3,1,1,1,1,'MO-V开发的无人MS。
为了保卫MO-V，以OZ的MD的资料为基础，将里奥改装而成的机体。
机体用途限定在宇宙战及保卫据点，脚部装上大型推进器，腕部则改装光束加农，并将不需要的零件全数排除。
生产费用低廉但战斗能力却很高，面对以比尔哥Ⅱ为主力的敌方部队也能相抗衡。',NULL,'{"unit_id": 1217000700, "unit_ssp_initial_release_set_id": 1217000700, "unit_ssp_custom_core_group_id": 1217000700, "unit_ssp_add_status_id": 100002, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100002, "ssp_hp": 206, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 23, "ssp_max_hp": 4119, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 458}}','D模组','master',1794971433,'v2026.11.18',NULL,'["2170", "2100"]');
INSERT OR REPLACE INTO "units" VALUES(1217000800,'里奥(MO-V宇宙式样)','里奥(MO-V宇宙式样)',1,1,0,0,'10000000021702100','2170','g2170u00800','OZ-06MS',1,1,1,1,5967,61,690,569,537,4,28164,122,3256,2683,2791,4,63728,242,7369,6071,6370,4,3,1,2,1,2,'隶属于MO-V的里奥宇宙战式样机。
里奥作为联合军的主力MS，在各地区都有配置，在MO-V也运用于殖民地的防卫上。
胸前涂有代表所属的「MO-V」字样，但性能与一般的里奥无异。
在MO-V遭到OZ普莱斯攻击时进行迎击，但由于驾驶员经验不足，面对敌方的杜拉士队陷入了苦战。',NULL,'{"unit_id": 1217000800, "unit_ssp_initial_release_set_id": 1217000800, "unit_ssp_custom_core_group_id": 1217000800, "unit_ssp_add_status_id": 100004, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100004, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 21, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 412}}','里奥(MO-V宇宙式样)','master',1794971433,'v2026.11.18',NULL,'["2170", "2100"]');
INSERT OR REPLACE INTO "units" VALUES(1217000900,'EWAC里奥','EWAC里奥',1,3,0,0,'10000000021702100','2170','g2170u00900','OZ-06MS-E2',1,1,1,1,6041,61,572,595,625,4,28510,138,2696,2807,2821,4,64510,281,6100,6352,6356,4,3,1,2,1,2,'隶属于OZ普莱斯的里奥侦查式样机型。
强化侦查、通信能力，头部装备巨大圆盘型雷达，并搭载多架摄影镜头。
为了取得「G-UNIT」的情报，被派遣到资源卫星殖民地「MO-V」的宙域一带，但遭到杰姆纳斯01发现，并发生交战。',NULL,'{"unit_id": 1217000900, "unit_ssp_initial_release_set_id": 1217000900, "unit_ssp_custom_core_group_id": 1217000900, "unit_ssp_add_status_id": 100013, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100013, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 23, "ssp_mobility": 24, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 435, "ssp_max_defense": 458, "ssp_max_mobility": 481}}','EWAC里奥','master',1794971433,'v2026.11.18',NULL,'["2170", "2100"]');
INSERT OR REPLACE INTO "units" VALUES(1217001000,'杜拉士(OZ普莱斯式样)','杜拉士(OZ普莱斯式样)',2,3,0,0,'10000000021702100','2170','g2170u01000','OZ-12MS',1,1,1,1,6134,66,681,615,682,4,32750,164,3635,3279,3477,4,60463,283,6710,6055,6402,4,3,1,3,1,2,'隶属于OZ普莱斯的杜拉士。
替代里奥成为OZ宇宙军的主力MS。
具备变成MA型态的可变构造，拥有高机动性，于OZ普莱斯亦有配置。
参加了OZ普莱斯对MO-V的攻击，与对方派出的里奥队交战，并将其压制。',NULL,'{"unit_id": 1217001000, "unit_ssp_initial_release_set_id": 1217001000, "unit_ssp_custom_core_group_id": 1217001000, "unit_ssp_add_status_id": 100012, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100012, "ssp_hp": 217, "ssp_en": 1, "ssp_attack": 24, "ssp_defense": 22, "ssp_mobility": 24, "ssp_max_hp": 4348, "ssp_max_en": 19, "ssp_max_attack": 481, "ssp_max_defense": 435, "ssp_max_mobility": 481}}','杜拉士(OZ普莱斯式样)','master',1794971433,'v2026.11.18',NULL,'["2170", "2100"]');
INSERT OR REPLACE INTO "units" VALUES(1217001100,'杜拉士(OZ普莱斯式样)【MA型态】','杜拉士(OZ普莱斯式样)【MA型态】',2,3,0,0,'10000000021702100','2170','g2170u01100','OZ-12MS',1,1,1,1,6134,66,647,584,751,5,32750,164,3452,3115,3826,5,60463,283,6374,5751,7043,5,3,3,1,1,1,'-',NULL,'{"unit_id": 1217001100, "unit_ssp_initial_release_set_id": 1217001100, "unit_ssp_custom_core_group_id": 1217001100, "unit_ssp_add_status_id": 100012, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100012, "ssp_hp": 217, "ssp_en": 1, "ssp_attack": 24, "ssp_defense": 22, "ssp_mobility": 24, "ssp_max_hp": 4348, "ssp_max_en": 19, "ssp_max_attack": 481, "ssp_max_defense": 435, "ssp_max_mobility": 481}}','杜拉士(OZ普莱斯式样)【MA型态】','master',1794971433,'v2026.11.18',NULL,'["2170", "2100"]');
INSERT OR REPLACE INTO "units" VALUES(1217001200,'里奥(OZ普莱斯式样)','里奥(OZ普莱斯式样)',2,1,0,0,'10000000021702100','2170','g2170u01200','OZ-06MS',1,1,1,1,6541,65,750,548,649,4,34928,155,4004,2924,3465,4,64484,266,7393,5399,6397,4,3,1,3,1,2,'隶属于OZ普莱斯的里奥。
泛用性及量产性都很出色的机体，作为联合军的主力MS被大量生产，也配置到OZ普莱斯。
基本上和一般的里奥没有太大的差异，但有施以专用的涂装配色。',NULL,'{"unit_id": 1217001200, "unit_ssp_initial_release_set_id": 1217001200, "unit_ssp_custom_core_group_id": 1217001200, "unit_ssp_add_status_id": 100003, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100003, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 19, "ssp_mobility": 23, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 389, "ssp_max_mobility": 458}}','里奥(OZ普莱斯式样)','master',1794971433,'v2026.11.18',NULL,'["2170", "2100"]');
INSERT OR REPLACE INTO "units" VALUES(1217001300,'雷欧尔','雷欧尔',3,3,0,0,'10000000021702100','2170','g2170u01300','OZ-06MS-SR2',1,1,1,1,6962,71,734,629,739,4,41490,192,4374,3745,4201,4,63728,283,6718,5753,6442,4,3,1,3,1,2,'隶属于OZ普莱斯的里奥特装机。
将里奥改装，作为克拉兹·谢尔维的专用机，强化机动力和运动性的高机动机型。
装备加长型光束矛，拥有傲人的格斗战性能。
虽然也有用在进攻MO-V，但面对高达机型的对手，性能稍显不足。',NULL,'{"unit_id": 1217001300, "unit_ssp_initial_release_set_id": 1217001300, "unit_ssp_custom_core_group_id": 1217001300, "unit_ssp_add_status_id": 100014, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100014, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 24, "ssp_defense": 21, "ssp_mobility": 24, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 481, "ssp_max_defense": 412, "ssp_max_mobility": 481}}','雷欧尔','master',1794971433,'v2026.11.18',NULL,'["2170", "2100"]');
INSERT OR REPLACE INTO "units" VALUES(1217001400,'雷欧斯','雷欧斯',3,1,0,0,'10000000021702100','2170','g2170u01400','OZ-06MS-SS1',1,1,1,1,6961,71,812,597,697,4,41486,183,4835,3553,4149,4,63722,268,7426,5457,6374,4,3,1,3,1,2,'隶属于OZ普莱斯的里奥特装机。
将里奥改装，作为罗杰·那多纳的专用机，提升整体性能。
武装虽然采标准配备，但不论射击战或格斗战都能应付，是平衡性很好的机体。
或许是驾驶员罗杰个人的喜好，双肩披上披风为其特征。
虽然也有用在进攻MO-V，但面对高达机型的对手，性能稍显不足。',NULL,'{"unit_id": 1217001400, "unit_ssp_initial_release_set_id": 1217001400, "unit_ssp_custom_core_group_id": 1217001400, "unit_ssp_add_status_id": 100003, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100003, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 19, "ssp_mobility": 23, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 389, "ssp_max_mobility": 458}}','雷欧斯','master',1794971433,'v2026.11.18',NULL,'["2170", "2100"]');
INSERT OR REPLACE INTO "units" VALUES(1217001500,'雷昂','雷昂',3,2,0,0,'10000000021702100','2170','g2170u01500','OZ-06MS-SN3',1,1,1,1,8055,57,769,732,631,4,48002,163,4581,4362,3355,4,73729,241,7037,6700,5131,4,3,1,3,1,2,'隶属于OZ普莱斯的里奥特装机。
将里奥改装，作为布鲁姆·布罗克斯的专用机，强化威力和防御力的重装机型。
具备能将里奥的机枪这类程度的攻击轻松挡下的装甲。
虽然也有用在进攻MO-V，但面对高达机型的对手，性能稍显不足。',NULL,'{"unit_id": 1217001500, "unit_ssp_initial_release_set_id": 1217001500, "unit_ssp_custom_core_group_id": 1217001500, "unit_ssp_add_status_id": 100015, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100015, "ssp_hp": 263, "ssp_en": 1, "ssp_attack": 25, "ssp_defense": 24, "ssp_mobility": 21, "ssp_max_hp": 5264, "ssp_max_en": 15, "ssp_max_attack": 503, "ssp_max_defense": 481, "ssp_max_mobility": 412}}','雷昂','master',1794971433,'v2026.11.18',NULL,'["2170", "2100"]');
INSERT OR REPLACE INTO "units" VALUES(1217001600,'高达亚斯克雷普欧斯','高达亚斯克雷普欧斯',3,1,0,0,'10000000021702100','2170','g2170u01600','OZ-10VMSX',1,1,1,1,6993,71,800,669,633,5,41678,166,4763,3985,4177,5,64016,242,7316,6122,6437,5,3,1,3,1,3,'OZ普莱斯将捕获到的高达杰姆纳斯02装备上追加装甲及强化零件而成的机体。
具备可变成接近战模式的变形构造，各种战场都能发挥高性能。
原机的「PX系统」也有保留下来，总和上攻击力更胜高达杰姆纳斯。
除了光束剑、急速射击等基本武器之外，近战模式还可使用特殊兵器「巨蛇钩爪」。',NULL,'{"unit_id": 1217001600, "unit_ssp_initial_release_set_id": 1217001600, "unit_ssp_custom_core_group_id": 1217001600, "unit_ssp_add_status_id": 100004, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100004, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 21, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 412}}','高达亚斯克雷普欧斯','master',1794971433,'v2026.11.18',NULL,'["2170", "2100"]');
INSERT OR REPLACE INTO "units" VALUES(1217001710,'高达亚斯克雷普欧斯(PX模式)','高达亚斯克雷普欧斯(PX模式)',4,3,0,0,'10000000021702100','2170','g2170u01700','OZ-10VMSX',1,1,1,1,8431,89,919,829,929,5,55471,260,6045,5453,5821,5,61388,282,6691,6035,6437,5,3,1,3,1,3,'OZ普莱斯的高机动强袭型MS。
本机是在掳获而来的高达杰姆纳斯02上，加装了追加装甲与强化零件而成的机体，
并具备可切换为近身战模式的变形结构，因此在各种战场上都能发挥出优异的性能。
除了光束剑、急速射击等一般武装外，在近身战模式下还可使用特殊兵器“巨蛇钩爪”。
此外，杰姆纳斯02所搭载的“PX系统”也被完整保留下来，在综合攻击力方面甚至凌驾于高达杰姆纳斯之上。',NULL,'{"unit_id": 1217001710, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1217001710, "unit_ssp_add_status_id": 100012, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100012, "ssp_hp": 217, "ssp_en": 1, "ssp_attack": 24, "ssp_defense": 22, "ssp_mobility": 24, "ssp_max_hp": 4348, "ssp_max_en": 19, "ssp_max_attack": 481, "ssp_max_defense": 435, "ssp_max_mobility": 481}}','高达亚斯克雷普欧斯(PX模式)','master',1794971433,'v2026.11.18',1217000500,'["2170", "2100"]');
INSERT OR REPLACE INTO "units" VALUES(1217001800,'墨丘利·休潘','墨丘利·休潘',3,2,0,0,'10000000021702100','2170','g2170u01800','OZ-13MSX2B-S',1,1,1,1,7317,60,765,805,596,4,43609,156,4556,4793,3552,4,66982,229,6998,7363,5455,4,3,1,3,1,2,'隶属于OZ普莱斯的墨丘利特装机。
将OZ开发的墨丘利进行改装，保留本体防御及牵制的特性，并把「行星防御系统」的数量增加一倍，与原机相比，性能获得全面提升。
虽然基本上是有人机，也能作为MD以无人机的形式使用。
用于OZ普莱斯的指挥官瓦尔达·法奇尔的亲卫队机。',NULL,'{"unit_id": 1217001800, "unit_ssp_initial_release_set_id": 1217001800, "unit_ssp_custom_core_group_id": 1217001800, "unit_ssp_add_status_id": 100018, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100018, "ssp_hp": 240, "ssp_en": 1, "ssp_attack": 25, "ssp_defense": 26, "ssp_mobility": 19, "ssp_max_hp": 4806, "ssp_max_en": 16, "ssp_max_attack": 503, "ssp_max_defense": 526, "ssp_max_mobility": 389}}','墨丘利·休潘','master',1794971433,'v2026.11.18',NULL,'["2170", "2100"]');
INSERT OR REPLACE INTO "units" VALUES(1217001900,'音速高达L.O.','音速高达L.O.',4,2,0,0,'10000000021702100','2170','g2170u01900','OZX-GU01LOB',1,1,1,1,8387,68,877,928,682,5,55184,190,5767,6103,4483,5,67177,227,7020,7431,5458,5,3,3,3,1,2,'高达杰姆纳斯01装备了高机动强化组件“03LOB系统”的型态。
通过组件系统内藏的发电机及推进器，输出和推力均提升至两倍以上。
也能通过简易变形，切换成高速飞行模式。
此外，为了辅助高速机动而装备了大型雷达，侦查能力也有提升。
主武装改成“轻量型加速冲锋枪”，也能利用内藏在双肩的反应式组件中的“推进光束加农”进行长距离炮击。',NULL,'{"unit_id": 1217001900, "unit_ssp_initial_release_set_id": 1217001900, "unit_ssp_custom_core_group_id": 1217001900, "unit_ssp_add_status_id": 100018, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100018, "ssp_hp": 240, "ssp_en": 1, "ssp_attack": 25, "ssp_defense": 26, "ssp_mobility": 19, "ssp_max_hp": 4806, "ssp_max_en": 16, "ssp_max_attack": 503, "ssp_max_defense": 526, "ssp_max_mobility": 389}}','音速高达L.O.','master',1794971433,'v2026.11.18',1217000701,'["2170", "2100"]');
INSERT OR REPLACE INTO "units" VALUES(1217002000,'音速高达L.O. [高速飞行模式]','音速高达L.O. [高速飞行模式]',4,2,0,0,'10000000021702100','2170','g2170u02000','OZX-GU01LOB',1,1,1,1,8387,68,833,882,750,5,55184,190,5477,5801,4931,5,67177,227,6668,7062,6003,5,3,3,1,1,1,'-',NULL,'{"unit_id": 1217002000, "unit_ssp_initial_release_set_id": 1217002000, "unit_ssp_custom_core_group_id": 1217002000, "unit_ssp_add_status_id": 100018, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100018, "ssp_hp": 240, "ssp_en": 1, "ssp_attack": 25, "ssp_defense": 26, "ssp_mobility": 19, "ssp_max_hp": 4806, "ssp_max_en": 16, "ssp_max_attack": 503, "ssp_max_defense": 526, "ssp_max_mobility": 389}}','音速高达L.O. [高速飞行模式]','master',1794971433,'v2026.11.18',NULL,'["2170", "2100"]');
INSERT OR REPLACE INTO "units" VALUES(1217002100,'幻象高达','幻象高达',4,1,0,0,'10000000021702100','2170','g2170u02100','OZ-19MASX',1,1,1,1,8050,81,924,761,715,5,52967,203,6073,5003,5214,5,64478,241,7394,6091,6357,5,3,3,3,1,2,'以OZ的试作型可变MS为基础，欧帝·班奈特秘密制造的机体。
攻击力、防御力及机动力全都经过优化的超高性能MS。
透过变形成MA型态、中间型态 (突击模式)，在各种环境下都能进行高机动战斗，输出更是高达杰姆纳斯的3倍以上。
此外，藉由搭载的「MSCS (精神同步型操纵系统)」，与驾驶员精神联接后能够自由自在地控制机体，减轻高机动时的操纵负荷。
装备了「光束矛」及「超绝MEGA粒子巨炮」等非常强力的武器，MA型态时也能发射破坏MEGA粒子炮。
双肩也装备了能使光束兵器无效化的「反射护罩」。',NULL,'{"unit_id": 1217002100, "unit_ssp_initial_release_set_id": 1217002100, "unit_ssp_custom_core_group_id": 1217002100, "unit_ssp_add_status_id": 100004, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100004, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 21, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 412}}','幻象高达','master',1794971433,'v2026.11.18',1217000100,'["2170", "2100"]');
INSERT OR REPLACE INTO "units" VALUES(1217002200,'幻象高达 [MA型态]','幻象高达 [MA型态]',4,1,0,0,'10000000021702100','2170','g2170u02200','OZ-19MASX',1,1,1,1,8050,81,878,723,787,5,52967,203,5771,4753,5739,5,64478,241,7026,5786,6998,5,3,3,1,1,1,'-',NULL,'{"unit_id": 1217002200, "unit_ssp_initial_release_set_id": 1217002200, "unit_ssp_custom_core_group_id": 1217002200, "unit_ssp_add_status_id": 100004, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100004, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 26, "ssp_defense": 22, "ssp_mobility": 21, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 526, "ssp_max_defense": 435, "ssp_max_mobility": 412}}','幻象高达 [MA型态]','master',1794971433,'v2026.11.18',NULL,'["2170", "2100"]');
INSERT OR REPLACE INTO "units" VALUES(1217002300,'高达班雷普欧斯','高达班雷普欧斯',4,2,0,0,'10000000021702100','2170','g2170u02300','OZ-10VMSX-2',1,1,1,1,8422,64,874,921,727,5,55416,200,5746,6059,4255,5,67459,240,6996,7376,5170,5,3,1,3,1,3,'将OZ普莱斯的高达亚斯克雷普欧斯加以改装的机体。
虽然外型上没有太大的差异，性能方面却有全面性的提升，并追加装备大型实体剑。
此外，仍保留原机的「PX系统」，具备高性能的同时，操作上也有难度。
葛兰夏丽欧攻防战时，由克拉兹·谢尔维搭乘，迎击MO-V高达部队。',NULL,'{"unit_id": 1217002300, "unit_ssp_initial_release_set_id": 1217002300, "unit_ssp_custom_core_group_id": 1217002300, "unit_ssp_add_status_id": 100016, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100016, "ssp_hp": 240, "ssp_en": 1, "ssp_attack": 25, "ssp_defense": 26, "ssp_mobility": 21, "ssp_max_hp": 4806, "ssp_max_en": 15, "ssp_max_attack": 503, "ssp_max_defense": 526, "ssp_max_mobility": 412}}','高达班雷普欧斯','master',1794971433,'v2026.11.18',NULL,'["2170", "2100"]');
INSERT OR REPLACE INTO "units" VALUES(1217002410,'高达班雷普欧斯(PX模式)','高达班雷普欧斯(PX模式)',4,1,0,0,'10000000021702100','2170','g2170u02400','OZ-10VMSX-2',1,1,1,1,8411,88,1060,792,836,5,55339,233,6970,5211,5785,5,61242,253,7713,5767,6407,5,3,1,3,1,3,'OZ普莱斯的高机动强袭型MS。
这架机体是由高达亚斯克雷普欧斯进一步改装而成的强化机体，整体性能也获得全面提升。
此外，“PX系统”也完整承袭自原机，虽然性能优异，却是一架相当难以驾驭的机体。
在葛兰夏丽欧攻防战中，曾迎击MO-V的高达部队，最后却因PX系统超载而自毁。',NULL,'{"unit_id": 1217002410, "unit_ssp_initial_release_set_id": 1217002410, "unit_ssp_custom_core_group_id": 1217002410, "unit_ssp_add_status_id": 100001, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100001, "ssp_hp": 217, "ssp_en": 1, "ssp_attack": 27, "ssp_defense": 21, "ssp_mobility": 22, "ssp_max_hp": 4348, "ssp_max_en": 19, "ssp_max_attack": 549, "ssp_max_defense": 412, "ssp_max_mobility": 435}}','高达班雷普欧斯(PX模式)','master',1794971433,'v2026.11.18',1217000601,'["2170", "2100"]');
INSERT OR REPLACE INTO "units" VALUES(1510000100,'高达吉利乌斯','高达吉利乌斯',4,2,0,0,'10000000000005100','5100','g5100u00100','EES-001',1,1,1,1,8820,69,898,851,684,5,58030,191,5907,5594,4495,5,70642,228,7191,6810,5472,5,3,3,3,1,2,'机体型号：EES-001
为配合国际组织“太阳系同盟”推动的“外太空探测计划”，伊斯特恩德公司开发了这款最新型的舱外活动用MS。
距今两百年前，人类在土星环发现了未知生物的遗骸“天鹅之母”。近年的研究证实，它其实是来自太阳系外的生命体。
人们相信，研究这种能够穿梭星际的生物，将有助于人类发展与突破，因此投入庞大的预算与人力，催生了“外太空探测计划”。
由于外太空对人类而言仍是未知领域，舱外活动用MS必须具备高度泛用性，以应对各种难以预测的突发状况。
数家公司历经长达数年的竞标与测试，最终脱颖而出的正是EES系列。
其开发理念为“实现人类梦想的次世代万能机”。
本机体的最大特色，在于搭载于背部的“羽翼延伸装置”。',NULL,'{"unit_id": 1510000100, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1510000100, "unit_ssp_add_status_id": 100019, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100019, "ssp_hp": 240, "ssp_en": 1, "ssp_attack": 27, "ssp_defense": 24, "ssp_mobility": 19, "ssp_max_hp": 4806, "ssp_max_en": 16, "ssp_max_attack": 549, "ssp_max_defense": 481, "ssp_max_mobility": 389}}','高达吉利乌斯','master',1793427821,'v2026.10.31',1510000100,'["5100"]');
INSERT OR REPLACE INTO "units" VALUES(1850003100,'魔鬼高达Jr.','魔鬼高达Jr.',4,3,0,0,'10000000085002000','2000','g8500u03100','JDG-0010X',1,1,1,1,7898,81,763,794,840,5,51966,237,5018,5222,5264,5,63260,283,6108,6357,6403,5,3,3,3,1,2,'魔鬼高达的后裔。
为本作的原创单位。
由魔鬼高达制造的死亡军团之中，实现独自进化的残存机体们合体之后进一步进化而成的机体。
与魔鬼高达相比显得非常小型，但具备出色能力，能操作模仿魔鬼高达四尊者的浮游炮，甚至还能操控人类的精神。
变本加厉地推行原型机“为了地球再生而抹杀人类”的思想，带着更高层次的目的“为了地球再生而奴役人类”展开行动。
在第13届高达武斗会的数年后，魔鬼高达的儿子累积了更多力量，准备挑战人类………',NULL,'{"unit_id": 1850003100, "unit_ssp_initial_release_set_id": 0, "unit_ssp_custom_core_group_id": 1850003100, "unit_ssp_add_status_id": 100013, "unit_ssp_material_consume_set_id": 1, "schedule_id": 2511209901, "stats": {"id": 100013, "ssp_hp": 229, "ssp_en": 1, "ssp_attack": 22, "ssp_defense": 23, "ssp_mobility": 24, "ssp_max_hp": 4577, "ssp_max_en": 19, "ssp_max_attack": 435, "ssp_max_defense": 458, "ssp_max_mobility": 481}}','魔鬼高达Jr.','master',1793427821,'v2026.10.31',NULL,'["2000"]');
COMMIT;
